package com.wipro.hibernate;import jakarta.persistence.*;import java.util.*;@Entity @Table(name="CONTINENT") public class Continent{@Id private int id;private String cname;@ElementCollection @CollectionTable(name="CONTINENT_COUNTRIES",joinColumns=@JoinColumn(name="CONTINENT_ID"))@MapKeyColumn(name="COUNTRY")@Column(name="CAPITAL")private Map<String,String>countries=new HashMap<>();public Continent(){}public Continent(int i,String n,Map<String,String>m){id=i;cname=n;countries=m;}}